from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'missing marker: {label}')
    if s.count(old)!=1:
        raise SystemExit(f'non-unique marker: {label} count={s.count(old)}')
    s=s.replace(old,new,1)

rep("const BUILD = 'V8.2.26';","const BUILD = 'V8.2.27';",'build')

rep('''  <div id="smart-relax-role-note"></div>\n  <div id="smart-relax-body">''','''  <div id="smart-relax-role-note"></div>\n  <div class="card" id="smart-relax-voice-card">\n    <h3>가이드 음성</h3>\n    <p class="muted" style="margin:-3px 0 10px">기기에서 제공하는 한국어 음성 중 하나를 선택하면 PMR · 심상화 · 명상에서 공통으로 사용합니다. 음성 이름만으로 성별을 정확히 알 수 없으므로 <b>미리듣기</b>로 원하는 부드러운 음성을 골라주세요.</p>\n    <select id="smart-relax-voice" aria-label="가이드 음성 선택"></select>\n    <div class="sp" style="align-items:center;gap:10px;margin-top:9px">\n      <button class="btn sec sm" id="smart-relax-voice-preview" style="width:auto;margin:0">▶ 미리듣기</button>\n      <span class="tiny" id="smart-relax-voice-status" style="flex:1;text-align:right"></span>\n    </div>\n    <p class="tiny" style="margin:8px 0 0">가이드는 조금 느린 속도로 읽습니다. 기기·브라우저에 따라 화면이 꺼지면 음성이 중단될 수 있습니다.</p>\n  </div>\n  <div class="note w hide" id="smart-relax-tts-unsupported" style="margin-bottom:12px">이 기기에서는 음성 안내 기능을 사용할 수 없습니다. 아래 글을 보며 연습할 수 있습니다.</div>\n  <div class="card hide" id="smart-relax-player">\n    <div class="sp" style="align-items:flex-start;gap:12px">\n      <div style="flex:1;min-width:0"><b id="smart-relax-player-title">가이드</b><div class="tiny" id="smart-relax-player-status" style="margin-top:3px">준비 중</div></div>\n    </div>\n    <div style="display:flex;gap:8px;margin-top:11px">\n      <button class="btn sec sm" id="smart-relax-player-pause" style="flex:1;margin:0">⏸ 일시정지</button>\n      <button class="btn ghost sm" id="smart-relax-player-stop" style="flex:1;margin:0">■ 종료</button>\n    </div>\n  </div>\n  <div id="smart-relax-body">''','voice controls')

rep('''        <p class="tiny" style="margin:8px 0 0">통증이나 불편함이 있는 부위는 억지로 힘주지 않고 건너뛰어도 됩니다.</p>\n      </div>''','''        <p class="tiny" style="margin:8px 0 0">통증이나 불편함이 있는 부위는 억지로 힘주지 않고 건너뛰어도 됩니다.</p>\n        <button class="btn sec sm" data-relax-guide="pmr" style="margin-top:11px">▶ PMR 가이드 듣기</button>\n      </div>''','pmr guide button')

rep('''        <div class="card tight"><b>4</b><div class="muted">어깨와 머리의 힘을 풀고 천천히 숨을 쉽니다.</div></div>\n      </div>''','''        <div class="card tight"><b>4</b><div class="muted">어깨와 머리의 힘을 풀고 천천히 숨을 쉽니다.</div></div>\n        <button class="btn sec sm" data-relax-guide="visual" style="margin-top:11px">▶ 심상화 가이드 듣기</button>\n      </div>''','visual guide button')

rep('''        <div class="card tight"><b>판단하지 않기</b><div class="muted">숫자를 잊거나 마음이 산만해져도 다시 1부터 시작합니다. 명상을 잘하고 못하고로 자신을 평가하지 않습니다.</div></div>\n      </div>''','''        <div class="card tight"><b>판단하지 않기</b><div class="muted">숫자를 잊거나 마음이 산만해져도 다시 1부터 시작합니다. 명상을 잘하고 못하고로 자신을 평가하지 않습니다.</div></div>\n        <button class="btn sec sm" data-relax-guide="meditation" style="margin-top:11px">▶ 명상 가이드 듣기</button>\n      </div>''','meditation guide button')

rep('''  $$('.pg').forEach(n => n.classList.remove('on'));\n  target.classList.add('on');\n  if(p === 'ai' && prev !== 'ai') ai.actionsOpen = false;''','''  $$('.pg').forEach(n => n.classList.remove('on'));\n  target.classList.add('on');\n  if(prev === 'smart-relax' && p !== 'smart-relax' && typeof relaxTtsStop === 'function') relaxTtsStop(false);\n  if(p === 'ai' && prev !== 'ai') ai.actionsOpen = false;''','stop tts on leave')

old='''/* ══════════ SMART Recovery · 이완 · 마음 가라앉히기 V8.2.26 ══════════\n   핸드북 Point 4의 감정과 함께 살아가기, PMR, 심상화, 명상 내용을\n   저장 없는 즉시 연습 화면으로 구성합니다. 기존 호흡 가이드는 충동 대응으로 연결합니다. */\nfunction drawSmartRelax(){\n const box=$('#smart-relax-body'),rn=$('#smart-relax-role-note'),bw=$('#smart-relax-breath-wrap'),bb=$('#smart-relax-breath');if(!box)return;\n if(rn)rn.innerHTML=famMode()?'<div class="note" style="margin-bottom:12px"><b>가족도 자신의 긴장을 돌봅니다.</b><br>상대를 진정시키거나 바꾸기 위한 기술이 아니라, 가족인 내가 내 감정과 몸의 긴장을 알아차리고 가라앉히기 위한 연습으로 사용합니다.</div>':'';\n const setAcc=(node,on)=>{if(!node)return;node.classList.toggle('on',!!on);const h=node.querySelector('[data-relax-toggle]');if(h)h.setAttribute('aria-expanded',on?'true':'false');};\n box.querySelectorAll('[data-relax-toggle]').forEach(b=>b.onclick=()=>{const target=b.closest('[data-relax-acc]'),was=target&&target.classList.contains('on');box.querySelectorAll('[data-relax-acc]').forEach(x=>setAcc(x,false));if(target&&!was)setAcc(target,true);});\n if(bw)bw.classList.toggle('hide',famMode());\n if(bb)bb.onclick=()=>{go('urge');toast('충동 대응을 시작한 뒤 타이머에서 ‘호흡 같이 하기’를 사용할 수 있습니다.');};\n}\n'''

new='''/* ══════════ SMART Recovery · 이완 · 마음 가라앉히기 V8.2.27 ══════════\n   화면 설명과 별도로 PMR · 심상화 · 명상 실천용 TTS 문장을 둡니다.\n   문장 사이의 쉼 시간을 따로 두어 사용자가 눈을 감고 따라갈 수 있게 합니다.\n   음성 선택은 회복기록 백업과 분리된 기기 설정으로만 저장합니다. */\nconst RELAX_TTS_VOICE_KEY='ohg.relaxVoice.v1';\nconst RELAX_TTS_RATE=.88;\nconst RELAX_TTS_GUIDES={\n pmr:{title:'점진적 근육 이완 · PMR',steps:[\n  ['편안하게 앉거나 누워보세요. 발과 손을 편하게 두고, 통증이 있는 부위는 억지로 힘주지 않아도 됩니다.',5000],\n  ['먼저 이마에 천천히 힘을 줍니다.',5000],\n  ['이제 힘을 놓고, 이마가 부드러워지는 느낌을 알아차립니다.',8000],\n  ['눈을 부드럽게 꼭 감고, 얼굴의 긴장을 느껴봅니다.',5000],\n  ['이제 눈과 볼의 힘을 풀어봅니다.',8000],\n  ['턱을 가볍게 다물어 힘을 줍니다.',5000],\n  ['턱을 놓고 입 주변의 힘도 함께 풀어봅니다.',8000],\n  ['어깨를 귀 쪽으로 천천히 올립니다.',5000],\n  ['이제 어깨를 내려놓고, 목과 어깨가 느슨해지는 것을 느껴봅니다.',10000],\n  ['양손을 가볍게 주먹 쥐고 팔에도 힘을 줍니다.',5000],\n  ['손을 펴고 팔 전체의 힘을 놓습니다.',10000],\n  ['배와 등에 가볍게 힘을 줍니다. 무리하지 않습니다.',5000],\n  ['이제 몸통의 힘을 풀고, 호흡이 자연스럽게 오가는 것을 느껴봅니다.',10000],\n  ['허벅지와 종아리, 발에 가볍게 힘을 줍니다.',5000],\n  ['이제 다리와 발의 힘을 모두 풀어봅니다.',10000],\n  ['머리부터 발끝까지 남아 있는 긴장이 있는지 천천히 살펴봅니다.',12000],\n  ['숨을 천천히 들이쉬고, 내쉬면서 남아 있는 힘을 한 번 더 놓아봅니다.',10000],\n  ['준비가 되면 손가락과 발가락을 가볍게 움직이고, 천천히 눈을 뜹니다.',0]\n ]},\n visual:{title:'심상화',steps:[\n  ['편안한 자세를 잡고, 가능하면 눈을 감아봅니다. 지금은 조용하고 안전한 장소를 떠올리는 시간입니다.',7000],\n  ['혼자 편안하게 머물 수 있는 장소 하나를 떠올려보세요. 실제로 가본 곳이어도 좋고, 상상 속의 장소여도 좋습니다.',15000],\n  ['그곳의 빛과 색, 주변의 모습을 천천히 살펴봅니다.',15000],\n  ['이제 그곳에서 들리는 소리에 귀를 기울여봅니다. 가까운 소리와 멀리 있는 소리를 차례로 떠올려보세요.',15000],\n  ['공기의 냄새와 온도도 느껴봅니다. 따뜻한지, 시원한지, 바람이 있는지도 천천히 알아차립니다.',15000],\n  ['몸이 닿아 있는 느낌을 떠올립니다. 발밑의 감촉, 의자나 바닥의 느낌, 피부에 닿는 공기를 느껴봅니다.',15000],\n  ['나를 편안하게 해주는 작은 세부 모습을 하나씩 더 채워봅니다.',20000],\n  ['어깨와 얼굴의 힘을 풀고, 숨을 천천히 들이쉬고 내쉽니다.',15000],\n  ['잠시 그 장소에 그대로 머물러봅니다. 무엇을 해야 할 필요는 없습니다.',20000],\n  ['준비가 되면 지금 있는 공간으로 천천히 돌아옵니다. 손과 발을 가볍게 움직이고 눈을 뜹니다.',0]\n ]},\n meditation:{title:'명상',steps:[\n  ['등을 편안하게 곧게 펴고 앉아봅니다. 손은 편하게 두고, 시선은 감거나 아래쪽에 둡니다.',6000],\n  ['첫 번째로, 숨을 조금 깊게 들이쉬고 천천히 내쉽니다.',8000],\n  ['두 번째로, 다시 천천히 들이쉬고 길게 내쉽니다.',8000],\n  ['세 번째로, 한 번 더 천천히 들이쉬고 내쉽니다.',8000],\n  ['이제 호흡을 바꾸려 하지 말고 자연스러운 리듬을 느껴봅니다.',7000],\n  ['하나.',3500],['둘.',3500],['셋.',3500],['넷.',3500],['다섯.',3500],\n  ['여섯.',3500],['일곱.',3500],['여덟.',3500],['아홉.',3500],['열.',5000],\n  ['생각이 떠오르면 밀어내지 않아도 됩니다. 생각이 있다는 것을 알아차린 뒤, 다시 호흡으로 천천히 돌아옵니다.',10000],\n  ['숫자를 잊었거나 마음이 멀리 갔다면 괜찮습니다. 다시 하나부터 시작하면 됩니다.',12000],\n  ['잠시 호흡만 느껴봅니다.',20000],\n  ['준비가 되면 주변의 소리를 다시 듣고, 손과 발을 움직인 뒤 천천히 눈을 뜹니다.',0]\n ]}\n};\nlet relaxTts={guide:'',index:0,token:0,timer:0,speaking:false,waiting:false,paused:false,voiceBound:false};\nfunction relaxTtsAvailable(){return !!(window.speechSynthesis&&window.SpeechSynthesisUtterance);}\nfunction relaxTtsVoiceId(v){return ((v.voiceURI||v.name||'')+'||'+(v.lang||''));}\nfunction relaxTtsSavedVoice(){try{return localStorage.getItem(RELAX_TTS_VOICE_KEY)||'';}catch(e){return '';}}\nfunction relaxTtsSaveVoice(id){try{if(id)localStorage.setItem(RELAX_TTS_VOICE_KEY,id);else localStorage.removeItem(RELAX_TTS_VOICE_KEY);}catch(e){}}\nfunction relaxTtsKoreanVoices(){\n if(!relaxTtsAvailable())return [];\n return window.speechSynthesis.getVoices().filter(v=>/^ko([_-]|$)/i.test(String(v.lang||'')));\n}\nfunction relaxTtsSelectedVoice(){const id=relaxTtsSavedVoice();return relaxTtsKoreanVoices().find(v=>relaxTtsVoiceId(v)===id)||null;}\nfunction relaxTtsRenderVoices(){\n const sel=$('#smart-relax-voice'),st=$('#smart-relax-voice-status');if(!sel||!relaxTtsAvailable())return;\n const saved=relaxTtsSavedVoice(),voices=relaxTtsKoreanVoices();\n sel.innerHTML='';const d=document.createElement('option');d.value='';d.textContent='기기 기본 한국어 음성';sel.appendChild(d);\n voices.forEach(v=>{const o=document.createElement('option');o.value=relaxTtsVoiceId(v);o.textContent=v.name+(v.lang?' · '+v.lang:'');sel.appendChild(o);});\n sel.value=voices.some(v=>relaxTtsVoiceId(v)===saved)?saved:'';\n if(st)st.textContent=voices.length?('한국어 음성 '+voices.length+'개'): '기기 기본 음성 사용';\n}\nfunction relaxTtsBindVoiceEvent(){\n if(relaxTts.voiceBound||!relaxTtsAvailable())return;relaxTts.voiceBound=true;\n const fn=()=>{if(cur==='smart-relax')relaxTtsRenderVoices();};\n if(window.speechSynthesis.addEventListener)window.speechSynthesis.addEventListener('voiceschanged',fn);\n else window.speechSynthesis.onvoiceschanged=fn;\n}\nfunction relaxTtsPrepareUtterance(text){\n const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';u.rate=RELAX_TTS_RATE;u.pitch=1;u.volume=1;\n const v=relaxTtsSelectedVoice();if(v)u.voice=v;return u;\n}\nfunction relaxTtsPlayer(show,title,status){\n const p=$('#smart-relax-player'),t=$('#smart-relax-player-title'),s=$('#smart-relax-player-status'),b=$('#smart-relax-player-pause');\n if(p)p.classList.toggle('hide',!show);if(t&&title!=null)t.textContent=title;if(s&&status!=null)s.textContent=status;if(b)b.textContent=relaxTts.paused?'▶ 계속':'⏸ 일시정지';\n}\nfunction relaxTtsStop(showToast){\n relaxTts.token++;if(relaxTts.timer){clearTimeout(relaxTts.timer);relaxTts.timer=0;}\n if(relaxTtsAvailable())try{window.speechSynthesis.cancel();}catch(e){}\n relaxTts.guide='';relaxTts.index=0;relaxTts.speaking=false;relaxTts.waiting=false;relaxTts.paused=false;relaxTtsPlayer(false,'','');\n if(showToast)toast('음성 가이드를 종료했습니다.');\n}\nfunction relaxTtsFinish(){const title=(RELAX_TTS_GUIDES[relaxTts.guide]||{}).title||'가이드';relaxTtsStop(false);toast(title+' 가이드를 마쳤습니다.');}\nfunction relaxTtsSpeakNext(token){\n if(token!==relaxTts.token||relaxTts.paused)return;const g=RELAX_TTS_GUIDES[relaxTts.guide];if(!g)return;\n if(relaxTts.index>=g.steps.length){relaxTtsFinish();return;}\n const step=g.steps[relaxTts.index],text=step[0],pause=Number(step[1]||0),pos=relaxTts.index+1,total=g.steps.length;\n relaxTts.speaking=true;relaxTts.waiting=false;relaxTtsPlayer(true,g.title,pos+' / '+total+' · 안내 중');\n const u=relaxTtsPrepareUtterance(text);\n u.onend=()=>{if(token!==relaxTts.token)return;relaxTts.speaking=false;relaxTts.index++;if(relaxTts.index>=g.steps.length){relaxTtsFinish();return;}relaxTts.waiting=true;relaxTtsPlayer(true,g.title,'잠시 쉬는 중');relaxTts.timer=setTimeout(()=>{if(token!==relaxTts.token)return;relaxTts.timer=0;relaxTts.waiting=false;relaxTtsSpeakNext(token);},pause);};\n u.onerror=e=>{if(token!==relaxTts.token)return;const err=String((e&&e.error)||'');if(err==='canceled'||err==='interrupted')return;relaxTtsStop(false);toast('음성 재생을 시작하지 못했습니다. 기기의 TTS 설정을 확인해주세요.');};\n try{window.speechSynthesis.speak(u);}catch(e){relaxTtsStop(false);toast('이 기기에서는 음성 재생을 시작하지 못했습니다.');}\n}\nfunction relaxTtsStart(kind){\n if(!relaxTtsAvailable()){toast('이 기기에서는 음성 안내를 지원하지 않습니다.');return;}const g=RELAX_TTS_GUIDES[kind];if(!g)return;\n relaxTtsStop(false);relaxTts.guide=kind;relaxTts.index=0;relaxTts.paused=false;const token=++relaxTts.token;relaxTtsPlayer(true,g.title,'시작합니다');relaxTtsSpeakNext(token);\n}\nfunction relaxTtsTogglePause(){\n if(!relaxTts.guide||!relaxTtsAvailable())return;\n if(!relaxTts.paused){relaxTts.paused=true;if(relaxTts.speaking)try{window.speechSynthesis.pause();}catch(e){}if(relaxTts.waiting&&relaxTts.timer){clearTimeout(relaxTts.timer);relaxTts.timer=0;}relaxTtsPlayer(true,(RELAX_TTS_GUIDES[relaxTts.guide]||{}).title||'가이드','일시정지됨');return;}\n relaxTts.paused=false;if(relaxTts.speaking){try{window.speechSynthesis.resume();}catch(e){}}else if(relaxTts.waiting){relaxTts.waiting=false;relaxTtsSpeakNext(relaxTts.token);}relaxTtsPlayer(true,(RELAX_TTS_GUIDES[relaxTts.guide]||{}).title||'가이드','계속 재생');\n}\nfunction relaxTtsPreview(){\n if(!relaxTtsAvailable()){toast('이 기기에서는 음성 안내를 지원하지 않습니다.');return;}relaxTtsStop(false);try{window.speechSynthesis.cancel();const u=relaxTtsPrepareUtterance('안녕하세요. 이 목소리로 이완 가이드를 천천히 안내해드릴게요.');window.speechSynthesis.speak(u);}catch(e){toast('미리듣기를 시작하지 못했습니다.');}\n}\nfunction drawSmartRelax(){\n const box=$('#smart-relax-body'),rn=$('#smart-relax-role-note'),bw=$('#smart-relax-breath-wrap'),bb=$('#smart-relax-breath');if(!box)return;\n if(rn)rn.innerHTML=famMode()?'<div class="note" style="margin-bottom:12px"><b>가족도 자신의 긴장을 돌봅니다.</b><br>상대를 진정시키거나 바꾸기 위한 기술이 아니라, 가족인 내가 내 감정과 몸의 긴장을 알아차리고 가라앉히기 위한 연습으로 사용합니다.</div>':'';\n const setAcc=(node,on)=>{if(!node)return;node.classList.toggle('on',!!on);const h=node.querySelector('[data-relax-toggle]');if(h)h.setAttribute('aria-expanded',on?'true':'false');};\n box.querySelectorAll('[data-relax-toggle]').forEach(b=>b.onclick=()=>{const target=b.closest('[data-relax-acc]'),was=target&&target.classList.contains('on');box.querySelectorAll('[data-relax-acc]').forEach(x=>setAcc(x,false));if(target&&!was)setAcc(target,true);});\n const supported=relaxTtsAvailable(),vc=$('#smart-relax-voice-card'),un=$('#smart-relax-tts-unsupported'),sel=$('#smart-relax-voice'),pv=$('#smart-relax-voice-preview'),pp=$('#smart-relax-player-pause'),ps=$('#smart-relax-player-stop');\n if(vc)vc.classList.toggle('hide',!supported);if(un)un.classList.toggle('hide',supported);box.querySelectorAll('[data-relax-guide]').forEach(b=>{b.disabled=!supported;b.onclick=()=>relaxTtsStart(b.dataset.relaxGuide);});\n if(supported){relaxTtsBindVoiceEvent();relaxTtsRenderVoices();if(sel)sel.onchange=()=>{relaxTtsStop(false);relaxTtsSaveVoice(sel.value);relaxTtsRenderVoices();toast('가이드 음성을 저장했습니다.');};if(pv)pv.onclick=relaxTtsPreview;if(pp)pp.onclick=relaxTtsTogglePause;if(ps)ps.onclick=()=>relaxTtsStop(true);}\n if(!relaxTts.guide)relaxTtsPlayer(false,'','');\n if(bw)bw.classList.toggle('hide',famMode());\n if(bb)bb.onclick=()=>{go('urge');toast('충동 대응을 시작한 뒤 타이머에서 ‘호흡 같이 하기’를 사용할 수 있습니다.');};\n}\n'''
